  if (baselineParamFields) {
    baselineParamFields.classList.toggle("has-fields", selected.size > 0);
  }
  syncBaselineLssdInputs();
  syncPairedNumberInputs(baselineDpEpsInput, headerBaselineDpEpsInput, state.baselineDpEps);
  syncPairedNumberInputs(
    baselineSquishRatioInput,
    headerBaselineSquishRatioInput,
    squishDisplayFromRaw(state.baselineSquishRatio)
  );
  const busy = compareRunButtons().some((btn) => btn.dataset.busy === "1");
  const canRun = canRunCompare() && selected.size > 0 && !busy;
  const traceReady = document.body.classList.contains("results-available");
  for (const btn of compareRunButtons()) {
    btn.disabled = !canRun;
